function profileFilled(clientId) { const p = loadProfile(clientId); return PROFILE_FIELDS.reduce((n, f) => n + (String(p[f.k] || '').trim() ? 1 : 0), 0) }
// Shared creative-fatigue thresholds (one set across all clients). CTR drops are
