// Monochrome sidebar icons (stroke = currentColor), so every nav item reads as
// one colour and matches the text weight - no multicolour emoji.
function NavIcon({ name }) {
  const P = {
    overview: <><rect x="3" y="3" width="7" height="7" rx="1.5" /><rect x="14" y="3" width="7" height="7" rx="1.5" /><rect x="3" y="14" width="7" height="7" rx="1.5" /><rect x="14" y="14" width="7" height="7" rx="1.5" /></>,
    trends: <><polyline points="3 16 9 10 13 14 21 6" /><polyline points="15 6 21 6 21 12" /></>,
    weekly: <><rect x="3" y="4" width="18" height="17" rx="2" /><path d="M3 9h18M8 2v4M16 2v4" /><path d="M8.5 15l2 2 4-4" /></>,
    forecast: <><path d="M3 5h18l-7 8v6l-4 2v-8z" /></>,
    cockpit: <><rect x="3" y="4" width="18" height="16" rx="2" /><path d="M3 9h18M8 4v5M16 4v5M8 20v-5M16 20v-5" /></>,
    curator: <><circle cx="13.5" cy="6.5" r="2.5" /><circle cx="17.5" cy="10.5" r="2.5" /><circle cx="8.5" cy="7.5" r="2.5" /><circle cx="6.5" cy="12.5" r="2.5" /><path d="M12 22a4 4 0 0 1 0-8 3 3 0 0 0 0-6" /></>,
    insights: <><path d="M3 12h4l2.5 7 4-15 2.5 8H21" /></>,
    update: <><rect x="3" y="5" width="18" height="14" rx="2" /><path d="M3.5 7l8.5 6 8.5-6" /></>,
    monthly: <><rect x="3" y="4" width="18" height="17" rx="2" /><path d="M3 9h18M8 2v4M16 2v4" /></>,
    report: <><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" /><path d="M14 2v6h6M8 13h8M8 17h6" /></>,
    social: <><path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z" /></>,
    settings: <><circle cx="12" cy="12" r="3" /><path d="M19.4 15a1.6 1.6 0 0 0 .32 1.77l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.6 1.6 0 0 0-2.73 1.13V21a2 2 0 0 1-4 0v-.08A1.6 1.6 0 0 0 7.13 19.4l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.6 1.6 0 0 0 3 13.87H3a2 2 0 0 1 0-4h.08A1.6 1.6 0 0 0 4.6 7.13l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.6 1.6 0 0 0 9.87 3H10a2 2 0 0 1 4 0v.08a1.6 1.6 0 0 0 2.73 1.13l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.6 1.6 0 0 0 21 9.87V10a2 2 0 0 1 0 4h-.08a1.6 1.6 0 0 0-1.52 1z" /></>,
  }[name] || null
  return <svg className="nav-svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.85" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{P}</svg>
}

// GoHighLevel-style client switcher for the sidebar: shows the active client
// (avatar + name + subline) as a chunky pill, and drops down a searchable list
// of every client. Picking one jumps straight to that client's workspace
// (the "Client View"). `idxOf` keeps avatar colours stable across the app.
function ClientSwitcher({ clients, active, onPick, idxOf }) {
  const [open, setOpen] = useState(false)
  const [q, setQ] = useState('')
  const ref = useRef(null)
  useEffect(() => {
    if (!open) return
    const onDoc = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false) }
    const onKey = (e) => { if (e.key === 'Escape') { setOpen(false); setQ('') } }
    document.addEventListener('mousedown', onDoc)
    document.addEventListener('keydown', onKey)
    return () => { document.removeEventListener('mousedown', onDoc); document.removeEventListener('keydown', onKey) }
  }, [open])
  const needle = q.trim().toLowerCase()
  const list = (needle ? clients.filter((c) => c.name.toLowerCase().includes(needle) || (c.industry || '').toLowerCase().includes(needle)) : clients).slice().sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' }))
  const pick = (c) => { onPick(c); setOpen(false); setQ('') }
  return (
    <div className={`csw ${open ? 'open' : ''}`} ref={ref}>
      <button className="csw-trigger" onClick={() => setOpen((o) => !o)} aria-haspopup="listbox" aria-expanded={open} title="Switch client">
        {active
          ? <Avatar id={active.id} name={active.name} i={idxOf(active)} sm />
          : <span className="avatar sm csw-ph">◎</span>}
        <span className="csw-txt">
          <b>{active ? active.name : 'Select a client'}</b>
          <small>{active ? (active.industry || 'Client workspace') : 'Jump to a client workspace'}</small>
        </span>
        <span className="csw-chev">▾</span>
      </button>
      {open && (
        <div className="csw-menu" role="listbox">
          <div className="csw-search"><input autoFocus placeholder="Search clients…" value={q} onChange={(e) => setQ(e.target.value)} /></div>
          <div className="csw-list">
            {list.length ? list.map((c) => {
              const sel = active && active.id === c.id
              return (
                <button key={c.id} className={`csw-item ${sel ? 'sel' : ''}`} role="option" aria-selected={sel} onClick={() => pick(c)}>
                  <Avatar id={c.id} name={c.name} i={idxOf(c)} sm />
                  <span className="csw-txt"><b>{c.name}</b><small>{c.industry || '-'}</small></span>
                  {sel && <span className="csw-tick">✓</span>}
                </button>
              )
            }) : <div className="csw-empty">No clients match “{q}”.</div>}
          </div>
        </div>
      )}
    </div>
  )
}

// ---- Deep-linkable navigation (URL <-> app state) --------------------------
// The whole app is a single page; these helpers mirror "where you are" into the
// query string (?v=view&c=clientId&t=tab) so a refresh restores the exact screen,
// Back/Forward work, and any screen can be linked to. The URL is never an
// authorisation boundary - every data request is still checked server-side, so a
// link to a client you can't see simply returns 403 and falls back to home.
const NAV_VIEWS = new Set(['overview', 'trends', 'weekly', 'forecast', 'cockpit', 'curator', 'insights', 'update', 'monthly', 'social', 'reports', 'settings', 'clients'])
function readNavUrl() {
  try { const p = new URLSearchParams(window.location.search); return { v: p.get('v'), c: p.get('c'), t: p.get('t'), s: p.get('s'), r: p.get('r'), from: p.get('from'), to: p.get('to'), wb: p.get('wb'), m: p.get('m') } } catch { return {} }
}
// writeNavUrl takes a PATCH: each key is set (truthy) or deleted (falsy); keys not
// present are left untouched, so partial writers (view vs range vs won-basis) compose
// and unowned params (e.g. ?invite=) survive.
/* Navigation audit trail.
   Hooked on the DERIVED location rather than on the nav handlers, so a deep
   link, a Back button press and a sidebar click all record identically - and a
   date-range change, which also rewrites the URL, records nothing.
   One beacon per view change, carrying the time spent on the PREVIOUS location.
   `keepalive` so the last hop still lands when the tab is closing. */
function useNavAudit(enabled, view, clientId, tab) {
  const here = useRef(null)   // { view, client, tab, at }
  const post = React.useCallback((entry, closing) => {
    const body = JSON.stringify({ view: entry.view, client: entry.client, tab: entry.tab, ms: entry.ms, ref: closing ? 'close' : null })
    try { fetch('/.netlify/functions/windsor?scope=navlog', { method: 'POST', headers: { 'content-type': 'application/json' }, body, keepalive: true }).catch(() => {}) } catch { /* never block navigation */ }
  }, [])
  // A location is recorded when it is LEFT, so the entry carries how long it was
  // open. The clock restarts rather than clearing, so a flush on tab-hide can't
  // double-count the time when the person comes back.
  const leave = React.useCallback((closing) => {
    const p = here.current
    if (!p) return
    const ms = Date.now() - p.at
    if (ms < 1000 && !closing) { return } // a bounce through a view isn't a visit
    post({ ...p, ms }, closing)
    here.current = { ...p, at: Date.now() }
  }, [post])
  useEffect(() => {
    if (!enabled) return
    leave(false)
    here.current = { view, client: clientId || null, tab: tab || null, at: Date.now() }
  }, [enabled, view, clientId, tab, leave])
  // The last location of a visit is only ever recorded here - nothing follows it.
  useEffect(() => {
    if (!enabled) return
    const onHide = () => { if (document.visibilityState === 'hidden') leave(true) }
    window.addEventListener('visibilitychange', onHide)
    window.addEventListener('pagehide', () => leave(true))
    return () => { window.removeEventListener('visibilitychange', onHide) }
  }, [enabled, leave])
}
function NavAudit({ on, view, clientId, tab }) {
  useNavAudit(on, view, clientId, tab)
  return null
}
function writeNavUrl(patch, push) {
  try {
    const p = new URLSearchParams(window.location.search)
    for (const [k, val] of Object.entries(patch)) { if (val === undefined) continue; val ? p.set(k, String(val)) : p.delete(k) }
    const qs = p.toString()
    const url = window.location.pathname + (qs ? `?${qs}` : '') + window.location.hash
    if (push) window.history.pushState(null, '', url); else window.history.replaceState(null, '', url)
  } catch { /* history API unavailable - navigation still works, just not deep-linked */ }
}
// A preset range stays RELATIVE in the URL (?r=last_30d re-derives on load, so a
// shared "last 30 days" link always means the recipient's last 30 days). A custom
// range FREEZES (?from=&to= exact dates). The default (last_30d) is left out to
// keep plain links clean.
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/
function rangePatch(range) {
  if (range && range.preset && range.preset !== 'last_30d') return { r: range.preset, from: null, to: null }
  if (range && !range.preset && range.from && range.to) return { r: null, from: range.from, to: range.to }
  return { r: null, from: null, to: null }
}
function rangeFromUrl(u) {
  if (u.r && PRESETS.some((x) => x.id === u.r)) return presetRange(u.r)
  if (u.from && u.to && DATE_RE.test(u.from) && DATE_RE.test(u.to)) return { from: u.from, to: u.to, label: `${u.from} → ${u.to}` }
  return null
}
const wbPatch = (wb) => ({ wb: wb === 'created' ? 'created' : null })

function Dashboard({ authUser, authEnabled, onLogout }) {
  const [data, setData] = useState(null)
  const [config, setConfig] = useState(null)
  const [err, setErr] = useState(null)
  const [view, setView] = useState(() => { const { v } = readNavUrl(); return v && NAV_VIEWS.has(v) ? v : 'overview' })
  const [picked, setPicked] = useState(null)
  // The client sub-tab (Caalano360 / Users / Meta Ads…) lives here too so the URL
  // can carry it; ClientWorkspace seeds from initialTab and reports changes back.
  const [clientTab, setClientTab] = useState(() => readNavUrl().t || 'overall')
  const navInitRef = useRef(false)
  const [theme, setTheme] = useState(() => { try { return localStorage.getItem('caalano_theme') || 'light' } catch { return 'light' } })
  const [range, setRange] = useState(() => rangeFromUrl(readNavUrl()) || presetRange('last_30d'))
  // Won basis: 'closed' (banked in the period, by won-date) or 'created' (won
  // among leads created in the period - the cohort/ROI view). Global + persisted.
  // Only Won/revenue/ROAS flip; leads, funnel and appointments stay created-basis.
  const [wonBasis, setWonBasis] = useState(() => {
    const wb = readNavUrl().wb; if (wb === 'created' || wb === 'closed') return wb // URL wins on a shared link
    try { return localStorage.getItem('caalano_wonbasis') === 'created' ? 'created' : 'closed' } catch { return 'closed' }
  })
  useEffect(() => { try { localStorage.setItem('caalano_wonbasis', wonBasis) } catch {} }, [wonBasis])
  // Mirror range + won-basis into the URL (replace, so they don't spam history).
  useEffect(() => { writeNavUrl(rangePatch(range), false) }, [range])
  useEffect(() => { writeNavUrl(wbPatch(wonBasis), false) }, [wonBasis])
  const [refreshKey, setRefreshKey] = useState(0)
  const [navOpen, setNavOpen] = useState(false)
  const [collapsed, setCollapsed] = useState(() => { try { return localStorage.getItem('caalano_sb') === '1' } catch { return false } })
  useEffect(() => { try { localStorage.setItem('caalano_sb', collapsed ? '1' : '0') } catch {} }, [collapsed])
  // Present mode: hide agency-internal (cost / spend / margin) figures so the
  // dashboard is safe to screen-share with a client. Not persisted - always
  // starts off so it can never be left on by accident.
  const [present, setPresent] = useState(false)
  const [showTerms, setShowTerms] = useState(false)
  const agency = useAgencyLive(range, refreshKey, wonBasis)
  useClientLogos() // one-time brand-logo sync from Caalano Systems (avatars)
  // Server-backed settings: re-render on hydrate/change; enabled is a derived
  // write-through value so client on/off persists to the server like the rest.
  useSettingsSync()
  const enabled = SETTINGS.enabled
  const setEnabled = (updater) => {
    const next = typeof updater === 'function' ? updater(SETTINGS.enabled) : updater
    SETTINGS.enabled = next; writeLS(ENABLED_KEY, next); saveSettingsRemote({ enabled: next }); bumpSettings()
  }
  // Super-Admin-only clients: hidden from everyone who isn't a superadmin (the
  // backend enforces the same; this is the UI half). Legacy/basic mode = owner,
  // so nothing is hidden there.
  const restricted = SETTINGS.restricted || {}
  const setRestricted = (updater) => {
    const next = typeof updater === 'function' ? updater(SETTINGS.restricted || {}) : updater
    SETTINGS.restricted = next; writeLS(RESTRICTED_KEY, next); saveSettingsRemote({ restricted: next }); bumpSettings()
  }
  const seeRestricted = !authEnabled || (authUser && authUser.role === 'superadmin')

  useEffect(() => { document.documentElement.setAttribute('data-theme', theme); try { localStorage.setItem('caalano_theme', theme) } catch {} }, [theme])
  useEffect(() => {
    hydrateSettings()
    // The roster and baked snapshot come from a function that filters them to
    // whoever is asking. They used to be static files under /data, published to
    // the site and served whole to any valid session - so a client's own browser
    // downloaded every other client's name, ad-account ids, spend and leads.
    fetch('/.netlify/functions/roster')
      .then((r) => { if (!r.ok) throw new Error('roster not available'); return r.json() })
      .then((j) => {
        if (!j || j.ok === false || !j.snapshot) throw new Error(j && j.error ? j.error : 'roster not available')
        setData(j.snapshot); setConfig(j.config || null)
      })
      .catch((e) => setErr(e.message))
  }, [])
  // Resolve a ?c=<clientId> deep link to the picked client once the client list
  // has loaded (the list is async, so this can't run at first render).
  useEffect(() => {
    if (navInitRef.current || !data) return
    navInitRef.current = true
    const { c, v } = readNavUrl()
    if (c) {
      const raw = (data.clients || []).find((x) => x.id === c) || (customClientList() || []).find((x) => x.id === c)
      // ?c= seeds the picked client, but only jump to the client dashboard when the
      // URL didn't ask for another view (e.g. ?v=cockpit&c= opens the Cockpit on
      // that client, not the client workspace).
      if (raw) { setPicked(raw); if (!v || v === 'clients') setView('clients') }
    }
  }, [data])
  // Browser Back / Forward: re-read the URL and re-apply it to state.
  useEffect(() => {
    const onPop = () => {
      const u = readNavUrl()
      setView(u.v && NAV_VIEWS.has(u.v) ? u.v : 'overview')
      setClientTab(u.t || 'overall')
      setRange(rangeFromUrl(u) || presetRange('last_30d'))
      if (u.wb === 'created' || u.wb === 'closed') setWonBasis(u.wb)
      if (u.c) { const raw = (data && (data.clients || []).find((x) => x.id === u.c)) || (customClientList() || []).find((x) => x.id === u.c); setPicked(raw || null) }
      else setPicked(null)
    }
    window.addEventListener('popstate', onPop)
    return () => window.removeEventListener('popstate', onPop)
  }, [data])

  if (err) return <div className="main"><div className="card">Failed to load data: {err}</div></div>
  if (!data) return <div className="main"><div className="card">Loading dashboard…</div></div>

  // snapshot.json clients don't carry the GHL location id, but config.json does.
  // Merge it in so the overview knows which clients have CRM (Caalano Systems)
  // and fires the ovrow requests - without this, r.c.ghl is undefined for every
  // client and the CRM columns never load.
  const ghlById = Object.fromEntries(((config && config.clients) || []).map((c) => [c.id, c.ghl]))
  // Apply any per-client override (UI-added clients, or name/industry/relink
  // edits) on top of a base client, matched by id. Account ids/names and
  // name/industry are taken from the override when present.
  const overrides = SETTINGS.clients || {}
  const applyOv = (c) => {
    const o = overrides[c.id]; if (!o) return c
    const g = (k, fb) => (o[k] !== undefined && o[k] !== null && o[k] !== '' ? o[k] : fb)
    return { ...c, name: g('name', c.name), industry: (o.industry !== undefined && o.industry !== '') ? o.industry : c.industry, meta: o.meta !== undefined ? o.meta : c.meta, google: o.google !== undefined ? o.google : c.google, ghl: o.ghl !== undefined ? o.ghl : c.ghl, ga4: o.ga4 !== undefined ? o.ga4 : c.ga4, metaName: o.metaName || c.metaName, googleName: o.googleName || c.googleName, ghlName: o.ghlName || c.ghlName, custom: true }
  }
  const custom = customClientList()
  const extras = custom.filter((cu) => !data.clients.some((c) => c.id === cu.id))
  const baseClients = [...data.clients.map(applyOv), ...extras].filter((c) => !isClientDeleted(c.id))
  const visibleClients = baseClients.filter((c) => enabled[c.id] !== false && canSeeClientFE(authUser, c.id) && (seeRestricted || !restricted[c.id])).map((c) => (c.ghl || !ghlById[c.id] ? c : { ...c, ghl: ghlById[c.id] }))
  const rows = computeRows(visibleClients, agency.data)
  // Config for the Settings page keeps deleted clients (so the Deleted filter can
  // restore them); the main app's baseClients above already hides them everywhere else.
  const cfgMerged = config ? { ...config, clients: [...(config.clients || []).map(applyOv), ...extras.filter((cu) => !(config.clients || []).some((c) => c.id === cu.id))] } : config
  const go = (v) => { setView(v); setPicked(null); setNavOpen(false); writeNavUrl({ v, c: null, t: null, m: null, s: v === 'settings' ? undefined : null }, true) }
  const openClient = (c) => { setPicked(c); setView('clients'); setClientTab('overall'); setNavOpen(false); writeNavUrl({ v: 'clients', c: c.id, t: 'overall', m: null, s: null }, true) }
  // Access role gates the whole shell. Viewers (clients) never reach agency-wide
  // views - they land straight in their assigned client(s).
  const role = authEnabled && authUser ? authUser.role : 'admin'
  const isViewer = role === 'viewer'
  const myClients = visibleClients
  // Monthly Reports capability (client-facing published reports). Viewers get it
  // only when granted; a viewer can be reports-only (no dashboard tabs).
  const canReports = isViewer ? !!(authUser && authUser.reports) : false
  const hasDashTabs = !isViewer || authUser.tabs == null || (Array.isArray(authUser.tabs) && authUser.tabs.length > 0)
  const viewerView = view === 'settings' ? 'settings'
    : (view === 'reports' && canReports) ? 'reports'
      : (hasDashTabs ? 'clients' : (canReports ? 'reports' : 'clients'))
  const curView = isViewer ? viewerView : view
  // Resolve a deep-linked ?c= client synchronously here too (not just in the async
  // effect) so a refresh straight onto a client URL doesn't flash the empty state.
  const urlClientId = readNavUrl().c
  const curPicked = curView === 'clients'
    ? ((picked && baseClients.some((c) => c.id === picked.id) && canSeeClientFE(authUser, picked.id) && (seeRestricted || !restricted[picked.id])) ? picked
      : (isViewer ? myClients[0]
        : ((urlClientId && baseClients.find((c) => c.id === urlClientId && canSeeClientFE(authUser, c.id) && (seeRestricted || !restricted[c.id]))) || picked)))
    : picked
  const idx = curPicked ? Math.max(0, baseClients.findIndex((c) => c.id === curPicked.id)) : 0
  return (
    <div className={`shell ${collapsed ? 'sb-collapsed' : ''} ${present ? 'present' : ''}`}>
      {/* Records where this person is. A component rather than a hook call in
          Dashboard: Dashboard returns early while data loads, so a hook here
          would change the hook count between renders. */}
      <NavAudit on={!!(authEnabled && authUser)} view={curView} clientId={curPicked && curPicked.id} tab={curView === 'clients' ? clientTab : null} />
      {navOpen && <div className="nav-overlay" onClick={() => setNavOpen(false)} />}
      {collapsed && <button className="sb-expand" onClick={() => setCollapsed(false)} aria-label="Show sidebar" title="Show sidebar">»</button>}
      <aside className={`side ${navOpen ? 'open' : ''}`}>
        <div className="brand"><div className="logo logo-360"><span>360</span></div><div><h1 className="brand-name">Caalano<span className="b360">360</span></h1><p>360° Reporting</p></div><button className="sb-toggle" onClick={() => setCollapsed(true)} aria-label="Collapse sidebar" title="Collapse sidebar">«</button><button className="side-close" onClick={() => setNavOpen(false)} aria-label="Close menu">✕</button></div>
        {(!isViewer || (myClients.length > 1 && hasDashTabs)) && myClients.length > 0 && (
          <ClientSwitcher clients={myClients} active={curView === 'clients' ? curPicked : null} onPick={openClient} idxOf={(c) => Math.max(0, baseClients.findIndex((x) => x.id === c.id))} />
        )}
        <nav className="nav">
          {!isViewer && <>
            <button className={curView === 'overview' ? 'active' : ''} onClick={() => go('overview')}><span className="ic"><NavIcon name="overview" /></span>Agency Overview</button>
            <button className={curView === 'trends' ? 'active' : ''} onClick={() => go('trends')}><span className="ic"><NavIcon name="trends" /></span>Daily Performance</button>
            <button className={curView === 'weekly' ? 'active' : ''} onClick={() => go('weekly')}><span className="ic"><NavIcon name="weekly" /></span>Weekly Traffic Light</button>
            {!isViewer && <button className={curView === 'forecast' ? 'active' : ''} onClick={() => go('forecast')}><span className="ic"><NavIcon name="forecast" /></span>Funnel Forecaster</button>}
            <button className={curView === 'cockpit' ? 'active' : ''} onClick={() => go('cockpit')}><span className="ic"><NavIcon name="cockpit" /></span>Creative Cockpit</button>
            <button className={curView === 'insights' ? 'active' : ''} onClick={() => go('insights')}><span className="ic"><NavIcon name="insights" /></span>Meta Insights</button>
            <button className={curView === 'update' ? 'active' : ''} onClick={() => go('update')}><span className="ic"><NavIcon name="update" /></span>Client Update</button>
            <button className={curView === 'monthly' ? 'active' : ''} onClick={() => go('monthly')}><span className="ic"><NavIcon name="monthly" /></span>Monthly Report</button>
            <button className={curView === 'social' ? 'active' : ''} onClick={() => go('social')}><span className="ic"><NavIcon name="social" /></span>Organic Social Media</button>
          </>}
          {isViewer && <>
            {canReports && <button className={curView === 'reports' ? 'active' : ''} onClick={() => go('reports')}><span className="ic"><NavIcon name="monthly" /></span>Monthly Reports</button>}
            {hasDashTabs && <>
              <div className="nav-lab">My dashboards</div>
              {myClients.length ? myClients.map((c) => <button key={c.id} className={curView === 'clients' && curPicked && curPicked.id === c.id ? 'active' : ''} onClick={() => openClient(c)}><span className="ic"><NavIcon name="report" /></span>{c.name}</button>) : <div className="nav-empty">No dashboards assigned yet - your admin will set these up.</div>}
            </>}
            {!hasDashTabs && !canReports && <div className="nav-empty">No access assigned yet - your admin will set these up.</div>}
          </>}
        </nav>
        <div className="side-foot">
          <button className={`settings-btn ${view === 'settings' ? 'active' : ''}`} onClick={() => go('settings')}><span className="ic"><NavIcon name="settings" /></span>Settings</button>
          {authUser && <div className="side-user"><span className="side-user-av">{(authUser.name || authUser.email || '?').trim().charAt(0).toUpperCase()}</span><div className="side-user-txt"><b>{authUser.name || authUser.email}</b><span>{ROLE_LABEL[authUser.role] || authUser.role}</span></div><button className="side-user-out" onClick={onLogout} title="Sign out">Sign out</button></div>}
          {/* Two deliberate lines rather than one that wraps mid-timestamp - the
              sidebar is too narrow to hold version, date and commit on one row. */}
          <div className="foot-build" title={`Caalano360 v${APP_VERSION} · Build ${__BUILD_TIME__}${__COMMIT_REF__ ? ` · commit ${__COMMIT_REF__}` : ''} · see CHANGELOG.md`}>
            <span className="fb-ver"><b>v{APP_VERSION}</b>{__COMMIT_REF__ ? <em>{__COMMIT_REF__}</em> : null}</span>
            <span className="fb-when">deployed {fmtBuildTime(__BUILD_TIME__)}</span>
          </div>
          {/* Standing notice. People forget what they signed on day one, so the
              claim sits where they work rather than only in a document. */}
          {showTerms ? <TermsViewer onClose={() => setShowTerms(false)} /> : null}
          <div className="foot-legal">
            © {new Date().getFullYear()} Caalano Digital. Caalano360 is proprietary software - its reports, metrics and
            design may not be copied, reproduced or reverse engineered.{' '}
            <button type="button" className="foot-legal-link" onClick={() => setShowTerms(true)}>Terms of use</button>
          </div>
        </div>
      </aside>

      <main className="main">
        <div className="mtop">
          <button className="burger" onClick={() => setNavOpen(true)} aria-label="Open menu">☰</button>
          <div className="logo logo-360 sm"><span>360</span></div>
          <b className="mtop-name">Caalano<span className="b360">360</span></b>
        </div>
        <div className="head">
          <div>
            <h2>{curView === 'overview' ? 'Agency Overview' : curView === 'trends' ? 'Daily Performance' : curView === 'weekly' ? 'Weekly Traffic Light' : curView === 'forecast' ? 'Funnel Forecaster' : curView === 'cockpit' ? 'Creative Cockpit' : curView === 'curator' ? 'Creative Curator' : curView === 'insights' ? 'Meta Insights' : curView === 'update' ? 'Client Update' : curView === 'monthly' ? 'Monthly Report' : curView === 'social' ? 'Organic Social Media' : curView === 'reports' ? 'Monthly Reports' : curView === 'settings' ? 'Settings' : isViewer ? 'Your report' : 'Clients'}</h2>
            <p>{curView === 'overview' ? 'Blended paid performance across all clients, live for the selected range.' : curView === 'trends' ? 'Rolling 3 / 7 / 14 / 21 / 28-day performance per client, each vs the prior equal window.' : curView === 'weekly' ? 'One client at a time, reported Monday-Sunday by ISO week - spend pacing, leads, appointments and wins vs KPI.' : curView === 'forecast' ? 'What a month of spend should turn into, stage by stage - from each client\u2019s own last 90 days, or a scenario you build.' : curView === 'cockpit' ? 'Every creative for a client, with performance, categorisation and AI strategy.' : curView === 'curator' ? 'Strategise new creatives to make: pick Format, Style, CTA, Audience and Angle for instant or AI concept ideas, and save the best to a board.' : curView === 'insights' ? 'Everything Meta-derived in one place - delivery health, creative fatigue and more, across every active Meta client.' : curView === 'update' ? 'Generate a client-ready account update (WhatsApp + email) for the selected range.' : curView === 'monthly' ? 'Build a frozen, slide-based monthly report for one client - campaign → ad set → creative → Google → Caalano360 → team → ROI. Export to PDF.' : curView === 'social' ? 'Organic Instagram + Facebook Page performance per client - followers, reach, engagement, best posts and audience, for the selected range.' : curView === 'reports' ? 'Your published monthly reports - frozen snapshots you can read on screen or download as a PDF.' : curView === 'settings' ? (isViewer ? 'Your account.' : 'Clients, key events, KPI targets and campaign links - saved to the server and shared across your team.') : isViewer ? 'Your live reporting for the selected range.' : 'Open any client for their Overall, CRM, Meta and Google workspace.'}</p>
          </div>
          <div className="spacer" />
          {curView !== 'settings' && curView !== 'monthly' && curView !== 'reports' && <DateRange range={range} onChange={setRange} busy={agency.status === 'loading'} />}
          {(curView === 'overview' || curView === 'weekly' || (curView === 'clients' && curPicked)) && <WonBasisToggle value={wonBasis} onChange={setWonBasis} />}
          {curView !== 'monthly' && curView !== 'reports' && <button className="refresh-btn" title="Refresh live data" onClick={() => setRefreshKey((k) => k + 1)}><span className={agency.status === 'loading' ? 'spin sm' : ''} style={{ display: 'inline-block' }}>⟳</span> Refresh</button>}
        </div>
        <ErrorBoundary key={curView + '|' + (curPicked && curPicked.id || '')} onHome={() => go(isViewer ? 'clients' : 'overview')}>
          {curView === 'overview' && !isViewer && <Overview rows={rows} currency={data.currency} periodLabel={rangeLabel(range)} live={agency.status === 'ok'} alerts={agency.data && agency.data.alerts} range={range} nonce={refreshKey} wonBasis={wonBasis} onPick={openClient} />}
          {curView === 'trends' && !isViewer && <TrendsTab rows={rows} currency={data.currency} nonce={refreshKey} onPick={openClient} />}
          {curView === 'weekly' && !isViewer && <WeeklyTab rows={rows} currency={data.currency} nonce={refreshKey} wonBasis={wonBasis} />}
          {curView === 'forecast' && !isViewer && <FunnelForecaster rows={rows} currency={data.currency} nonce={refreshKey} />}
          {curView === 'cockpit' && !isViewer && <CreativeCockpitPage clients={visibleClients} currency={data.currency} range={range} nonce={refreshKey} authUser={authUser} />}
          {curView === 'insights' && !isViewer && <MetaInsightsPage clients={visibleClients} currency={data.currency} range={range} nonce={refreshKey} />}
          {curView === 'update' && !isViewer && <ClientUpdatePage clients={visibleClients} currency={data.currency} range={range} nonce={refreshKey} authUser={authUser} />}
          {curView === 'monthly' && !isViewer && <MonthlyReport clients={visibleClients} currency={data.currency} authUser={authUser} />}
          {curView === 'reports' && isViewer && canReports && <ClientReports clients={myClients} currency={data.currency} authUser={authUser} />}
          {curView === 'social' && !isViewer && <SocialDashboard clients={visibleClients} range={range} nonce={refreshKey} />}
          {curView === 'settings' && <SettingsPage config={cfgMerged} enabled={enabled} setEnabled={setEnabled} restricted={restricted} setRestricted={setRestricted} currency={data.currency} authUser={authUser} authEnabled={authEnabled} theme={theme} setTheme={setTheme} onPick={(c) => openClient(baseClients.find((x) => x.id === c.id) || c)} />}
          {curView === 'clients' && curPicked && <ClientWorkspace client={curPicked} index={idx} data={data} config={cfgMerged} range={range} nonce={refreshKey} wonBasis={wonBasis} authUser={authUser} initialTab={clientTab} onTabChange={(t) => { setClientTab(t); writeNavUrl({ v: 'clients', c: curPicked.id, t }, false) }} onBack={isViewer ? null : () => go('overview')} />}
          {curView === 'clients' && !curPicked && <div className="card empty-deep"><div className="big">👋</div><b>No report is assigned to your account yet.</b><p style={{ maxWidth: 460, margin: '8px auto 0' }}>Your Caalano admin will assign your client dashboard shortly.</p></div>}
        </ErrorBoundary>
      </main>
    </div>
  )
}

// Auth gate. Decides between the login/setup/accept screens and the dashboard.
// When the login system is disabled (AUTH_SECRET unset) it renders the dashboard
// straight through, preserving the app's previous single-password behaviour.
export default function App() {
  const [auth, setAuth] = useState({ status: 'loading' })
  const inviteToken = (() => { try { return new URLSearchParams(window.location.search).get('invite') } catch { return null } })()
  const previewTerms = (() => { try { return new URLSearchParams(window.location.search).get('preview') === 'terms' } catch { return false } })()
  const check = () => authApi('me').then((r) => {
    if (!r || r.ok === false && r.enabled === false) setAuth({ status: 'ready', enabled: false, user: null })
    else if (r.enabled === false) setAuth({ status: 'ready', enabled: false, user: null })
    else setAuth({ status: 'ready', enabled: true, user: r.user || null, needsSetup: !!r.needsSetup })
  }).catch(() => setAuth({ status: 'ready', enabled: false, user: null }))
  useEffect(() => { check() }, [])
  const clearInvite = () => { try { window.history.replaceState({}, '', window.location.pathname) } catch {} }
  const onSignedIn = (user) => { clearInvite(); setAuth({ status: 'ready', enabled: true, user, needsSetup: false }) }
  const onLogout = () => { authApi('logout', { method: 'POST' }).finally(() => setAuth({ status: 'ready', enabled: true, user: null, needsSetup: false })) }

  if (auth.status === 'loading') return <div className="auth-screen"><div className="auth-card"><Spinner label="Loading…" /></div></div>
  // Accept-invite deep link takes priority (a signed-out invitee, or a new
  // person on a shared machine, should always land on the invite flow).
  if (auth.enabled && inviteToken && !auth.user) return <AcceptInvite token={inviteToken} onSignedIn={onSignedIn} />
  if (auth.enabled && auth.needsSetup) return <SetupAdmin onSignedIn={onSignedIn} />
  if (auth.enabled && !auth.user) return <LoginForm onSignedIn={onSignedIn} />
  // Terms gate. Sits between signing in and the dashboard so acceptance is a
  // real decision rather than a banner someone scrolls past - and so there is a
  // signed record before any client data is on screen. Only applies when the
  // multi-user system is on; the legacy shared-password mode has no identity to
  // record an acceptance against.
  // The server decides this (`needsTerms`), so a version bump alone doesn't drag
  // everyone back through the gate - a signature stands until the minimum
  // accepted version is deliberately raised. The fallback covers an older
  // function still being live mid-deploy: sign only if nothing is on file.
  const needsTerms = auth.user && (auth.user.needsTerms !== undefined ? auth.user.needsTerms : !auth.user.termsVersion)
  if (auth.enabled && auth.user && needsTerms) {
    return <TermsGate
      user={auth.user}
      onLogout={onLogout}
      onAccepted={(r) => setAuth((a) => ({ ...a, user: { ...a.user, termsVersion: r.version, termsAcceptedAt: r.acceptedAt, needsTerms: false } }))}
    />
  }
  // ?preview=terms re-opens the signing screen for someone who has already
  // signed, so the gate can be demonstrated or re-read without bumping the
  // version for everyone. Accepting is inert here; leaving is a plain reload.
  if (auth.enabled && auth.user && previewTerms) {
    return <TermsGate preview user={auth.user} onAccepted={() => {}} onLogout={() => { clearInvite(); window.location.reload() }} />
  }
  return (
    <ViewerCtx.Provider value={!!(auth.enabled && auth.user && auth.user.role === 'viewer')}>
      {/* Legacy single-password mode has no identity, so it counts as owner - the
          same rule `isSuper` uses everywhere else. */}
      <SuperCtx.Provider value={!auth.enabled || !!(auth.user && auth.user.role === 'superadmin')}>
        <Dashboard authUser={auth.user} authEnabled={auth.enabled} onLogout={onLogout} /><GlobalLoadIndicator />
      </SuperCtx.Provider>
    </ViewerCtx.Provider>
  )
}
